opolar output\nVarious Cutting, Coagulation and Bipolar Modes\nSpray Coagulation Function\n*Large vessel sealing system\nEndo Mode\nBipolar Cutting Mode\n\n','Touch screen','','inherit','closed','closed','','1238-revision-v1','','','2017-11-10 17:25:37','2017-11-10 16:25:37','a:4:{s:7:\"post_id\";i:1238;s:9:\"post_hash\";s:44:\"layers_page_a5da4cb4893a1e618863fe58a9d25228\";s:10:\"post_title\";s:12:\"Touch screen\";s:11:\"widget_data\";a:1:{s:24:\"obox-layers-builder-1238\";a:2:{s:22:\"layers-widget-slide-30\";a:14:{s:26:\"autoheight_slides-CHECKBOX\";s:2:\"on\";s:12:\"slide_height\";s:3:\"550\";s:6:\"design\";a:1:{s:8:\"advanced\";a:5:{s:7:\"padding\";a:4:{s:3:\"top\";s:0:\"\";s:5:\"right\";s:0:\"\";s:6:\"bottom\";s:0:\"\";s:4:\"left\";s:0:\"\";}s:6:\"margin\";a:4:{s:3:\"top\";s:0:\"\";s:5:\"right\";s:0:\"\";s:6:\"bottom\";s:0:\"\";s:4:\"left\";s:0:\"\";}s:6:\"anchor\";s:0:\"\";s:11:\"customclass\";s:0:\"\";s:9:\"customcss\";s:0:\"\";}}s:18:\"show_slider_arrows\";s:2:\"on\";s:27:\"show_slider_arrows-CHECKBOX\";s:2:\"on\";s:16:\"show_slider_dots\";s:2:\"on\";s:25:\"show_slider_dots-CHECKBOX\";s:2:\"on\";s:18:\"slider_arrow_color\";s:0:\"\";s:14:\"animation_type\";s:5:\"slide\";s:24:\"autoplay_slides-CHECKBOX\";s:2:\"on\";s:10:\"slide_time\";s:0:\"\";s:11:\"focus_slide\";s:1:\"0\";s:9:\"slide_ids\";s:3:\"216\";s:6:\"slides\";a:1:{i:216;a:4:{s:6:\"design\";a:6:{s:10:\"background\";a:6:{s:5:\"color\";s:7:\"#f8f8f8\";s:5:\"image\";s:0:\"\";s:6:\"repeat\";s:9:\"no-repeat\";s:8:\"position\";s:6:\"center\";s:16:\"stretch-CHECKBOX\";s:2:\"on\";s:15:\"darken-CHECKBOX\";s:2:\"on\";}s:13:\"featuredimage\";s:63:\"http://www.ig-medical.com/wp-content/uploads/2017/11/MAX-VI.png\";s:13:\"featuredvideo\";s:0:\"\";s:10:\"imagealign\";s:9:\"image-top\";s:5:\"fonts\";a:4:{s:4:\"size\";s:5:\"large\";s:5:\"align\";s:11:\"text-center\";s:5:\"color\";s:0:\"\";s:13:\"excerpt-color\";s:0:\"\";}s:8:\"advanced\";a:1:{s:11:\"customclass\";s:0:\"\";}}s:5:\"title\";s:19:\"MAX Series - MAX VI\";s